import pandas as pd, numpy as np
from scipy.optimize import least_squares
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:pd.read_csv(f) for f in files}
def lagf(u,tau):
    dt=0.001; x=u[0]; out=np.empty(len(u)); a=min(dt/tau,1.0)
    for i in range(len(u)):
        out[i]=x; x+=a*(u[i]-x)
    return out
def simQ(p,d):
    a,b,c,d_,t1,t2=p
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; V0=V[0]; Q0=d.reactive_power_pu.values[0]
    x1=lagf(V-V0,max(t1,0.001)); x2=lagf(V-V0,max(t2,0.001))
    return Q0+a*(Vs-V0)+b*(V-V0)+c*x1+d_*x2
def res(p,fl): return np.concatenate([simQ(p,D[k])-D[k].reactive_power_pu.values for k in fl])
best=None
for t1 in [0.01,0.05]:
  for t2 in [0.3,1.0,3.0]:
    s=least_squares(res,[2.5,0,-1,-1,t1,t2],args=(files,),bounds=([-50,-50,-50,-50,0.001,0.001],[50,50,50,50,20,20]))
    if best is None or s.cost<best.cost: best=s
print(np.round(best.x,4), np.sqrt(np.mean(best.fun**2)))
for k in files:
    print(k, np.sqrt(np.mean((simQ(best.x,D[k])-D[k].reactive_power_pu.values)**2)))

