import pandas as pd, numpy as np
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_fault_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
val=['val/A_val_vref_op2.csv','val/A_val_load_op1.csv']
D={f:pd.read_csv(f) for f in files+val}
def feat(d,kind):
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; P=d.active_power_pu.values; th=d.bus_angle_rad.values
    cols=[Vs-V[0],V-V[0]]
    if 'P' in kind: cols.append(P-P[0])
    if 'th' in kind: cols.append(th-th[0])
    return np.column_stack(cols)
for kind in ['static','P','th','Pth']:
    X=[];Y=[]
    for f in files:
        d=D[f]; X.append(feat(d,kind)); Y.append(d.reactive_power_pu.values-d.reactive_power_pu.values[0])
    X=np.vstack(X);Y=np.concatenate(Y); c,*_=np.linalg.lstsq(X,Y,rcond=None)
    out=[]
    for f in val:
        d=D[f]; pred=d.reactive_power_pu.values[0]+feat(d,kind)@c
        out.append(round(float(np.sqrt(np.mean((pred-d.reactive_power_pu.values)**2))),4))
    print(kind,np.round(c,3),round(np.sqrt(np.mean((X@c-Y)**2)),4),out)

